// Cere prețurile OPCOM PZU (15 min) pentru AZI și, după ora 13, pentru MÂINE, doar dacă lipsesc.
// Rulează la pornire și la fiecare 10 minute (vezi nodul inject).
const preturi = flow.get("opcom_preturi") || {};
const local = new Date(new Date().toLocaleString("en-US", { timeZone: "Europe/Bucharest" }));
function zi(offset) {
    const d = new Date(local); d.setDate(d.getDate() + offset);
    const p = x => String(x).padStart(2, "0");
    return { key: d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate()),
             opcom: p(d.getDate()) + "/" + p(d.getMonth() + 1) + "/" + d.getFullYear() };
}
const zile = [zi(0)];
if (local.getHours() >= 13) zile.push(zi(1));   // OPCOM publică ziua de mâine în jur de 13:00–14:30
const cereri = zile.filter(z => !preturi[z.key] || preturi[z.key].length === 0).map(z => ({
    url: "https://www.opcom.ro/rapoarte-pzu-raportPIP-export-csv/" + z.opcom + "/ro?resolution=15",
    method: "GET", opcomZi: z.key
}));
if (cereri.length === 0) { node.status({ fill: "green", shape: "dot", text: "prețuri deja descărcate: " + zile.map(z => z.key).join(", ") }); return null; }
node.status({ fill: "blue", shape: "dot", text: "cer: " + cereri.map(c => c.opcomZi).join(", ") });
return [cereri];

// Citește CSV-ul OPCOM și salvează în flow "opcom_preturi" = { "AAAA-LL-ZZ": [ {interval, ora, pret_lei_mwh} ] }
const text = typeof msg.payload === "string" ? msg.payload : "";
const preturi = [];
text.split("\n").forEach(linie => {
    linie = linie.trim();
    if (!linie.startsWith('"Romania"')) return;
    const col = linie.split(",").map(c => c.replace(/"/g, "").trim());
    const interval = parseInt(col[1]), pret = parseFloat(col[2]);
    if (isNaN(interval) || isNaN(pret)) return;
    const min = (interval - 1) * 15;
    preturi.push({ interval: interval, ora: String(Math.floor(min / 60)).padStart(2, "0") + ":" + String(min % 60).padStart(2, "0"), pret_lei_mwh: pret });
});
if (msg.statusCode !== 200 || preturi.length === 0) {
    node.status({ fill: "yellow", shape: "ring", text: msg.opcomZi + ": încă fără prețuri (cod " + msg.statusCode + ")" });
    return null;
}
const toate = flow.get("opcom_preturi") || {};
toate[msg.opcomZi] = preturi;
Object.keys(toate).sort().slice(0, -3).forEach(k => delete toate[k]);   // păstrăm ultimele 3 zile
flow.set("opcom_preturi", toate);
const v = preturi.map(p => p.pret_lei_mwh);
node.status({ fill: "green", shape: "dot", text: msg.opcomZi + ": " + preturi.length + " intervale, " + Math.min(...v) + "–" + Math.max(...v) + " lei/MWh" });
return { topic: "publica" };   // publică imediat în HA

// ===================== SETĂRI (aici modifici) =====================
const HA_URL   = "http://homeassistant.local:8123";   // adresa Home Assistant (ex. http://192.168.1.10:8123)
const HA_TOKEN = "PUNE_AICI_TOKEN_HA";                  // Profil HA → Securitate → Long-lived access token
const ENTITATE = "sensor.opcom_pret_acum";              // NU schimba: cardul citește acest senzor
// ==================================================================
// Trimite în HA prețul curent + listele pe 15/30/60 min pentru azi și mâine.
if (HA_TOKEN.startsWith("PUNE_AICI")) { node.status({ fill: "red", shape: "ring", text: "completează HA_URL și HA_TOKEN în acest nod" }); return null; }
const r2 = x => Math.round(x * 100) / 100;
const local = new Date(new Date().toLocaleString("en-US", { timeZone: "Europe/Bucharest" }));
const p = x => String(x).padStart(2, "0");
const cheie = d => d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate());
const maine = new Date(local); maine.setDate(maine.getDate() + 1);
const aziKey = cheie(local), maineKey = cheie(maine);
const opcom = flow.get("opcom_preturi") || {};
const pAzi = opcom[aziKey] || [], pMaine = opcom[maineKey] || [];
const intervalAcum = Math.floor((local.getHours() * 60 + local.getMinutes()) / 15) + 1;
const pretAcum = (pAzi.find(x => x.interval === intervalAcum) || {}).pret_lei_mwh;
function minmax(l) { const v = l.map(x => x.pret_lei_mwh); return v.length ? { min: Math.min(...v), max: Math.max(...v), medie: r2(v.reduce((a, b) => a + b, 0) / v.length) } : null; }
// prețuri pe 15 min (n=1) și medii pe 30 min (n=2) și 60 min (n=4), în ordinea intervalelor
function grupe(l, n) {
    const s = l.slice().sort((x, y) => x.interval - y.interval), out = [];
    for (let i = 0; i < s.length; i += n) { const g = s.slice(i, i + n); out.push(r2(g.reduce((a, x) => a + x.pret_lei_mwh, 0) / g.length)); }
    return out;
}
msg.url = HA_URL.replace(/\/+$/, "") + "/api/states/" + ENTITATE;
msg.method = "POST";
msg.headers = { "Authorization": "Bearer " + HA_TOKEN, "Content-Type": "application/json" };
msg.payload = {
    state: pretAcum !== undefined ? String(pretAcum) : "unknown",
    attributes: {
        interval: intervalAcum, azi: minmax(pAzi), maine: minmax(pMaine), maine_disponibil: pMaine.length > 0,
        data_azi: aziKey, data_maine: maineKey,
        azi_15: grupe(pAzi, 1), azi_30: grupe(pAzi, 2), azi_60: grupe(pAzi, 4),
        maine_15: grupe(pMaine, 1), maine_30: grupe(pMaine, 2), maine_60: grupe(pMaine, 4),
        unit_of_measurement: "lei/MWh", friendly_name: "OPCOM Pret acum", icon: "mdi:flash"
    }
};
node.status({ fill: pAzi.length ? "blue" : "yellow", shape: "dot",
    text: (pretAcum !== undefined ? pretAcum + " lei/MWh" : "fără preț azi") + " · mâine " + (pMaine.length ? "da" : "nu") });
return msg;

// Arată dacă HA a primit senzorul (200 = actualizat, 201 = creat)
if (msg.statusCode === 200 || msg.statusCode === 201) {
    node.status({ fill: "green", shape: "dot", text: "HA OK la " + new Date().toLocaleTimeString("ro-RO", { timeZone: "Europe/Bucharest" }) });
} else {
    node.status({ fill: "red", shape: "ring", text: "HA a răspuns " + msg.statusCode + (msg.statusCode === 401 ? " — token greșit" : "") });
    node.warn("Eroare HA " + msg.statusCode + ": " + JSON.stringify(msg.payload).slice(0, 200));
}
return null;
